"use strict";
// No state of its own: under Node each thread has an instance of this
// module, and in a compiled program all threads reach one.
class Item {
  constructor(value) {
    this.value = value;
    this.label = "item-" + value;
  }
}
exports.Item = Item;
exports.make = (value) => new Item(value);
exports.describe = (item) => `${item.label}:${item.value * 2}`;
exports.tally = (a, b) => `${a}+${b}=${a + b}`;
